for fqn,body in S.items():
    pkg,name=fqn.rsplit('.',1)
    p=os.path.join(ROOT,*pkg.split('.'),name+'.java')
    os.makedirs(os.path.dirname(p),exist_ok=True)
    open(p,'w').write('package %s;\n%s\n'%(pkg,body))
print(len(S))
